      update((node << 1) | 1, mid + 1, r, idx, val);
    }
    tree[node] = merge(tree[node << 1], tree[(node << 1) | 1]);
  }

  function query(node, l, r, ql, qr) {
    if (ql <= l && r <= qr) {
      return tree[node];
    }
    const mid = (l + r) >> 1;
    if (qr <= mid) {
      return query(node << 1, l, mid, ql, qr);
    }
    if (ql > mid) {
      return query((node << 1) | 1, mid + 1, r, ql, qr);
    }
    const leftRes = query(node << 1, l, mid, ql, qr);
    const rightRes = query((node << 1) | 1, mid + 1, r, ql, qr);
    return merge(leftRes, rightRes);
  }

  build(1, 1, N);

  const out = [];
  for (let m = 0; m < M; m++) {
    const type = readInt();
    if (type === 1) {
      const idx = readInt();
      const val = readInt();
      update(1, 1, N, idx, val);
    } else {
      const l = readInt();
      const r = readInt();
      const res = query(1, 1, N, l, r);
      out.push(res.ans);
      if (out.length >= 10000) {
        process.stdout.write(out.join('\n') + '\n');
        out.length = 0;
      }
    }
  }

  if (out.length > 0) {
    process.stdout.write(out.join('\n') + '\n');
  }
}

solve();
